/* Real task history, model capabilities and platform-point accounting. */
'use strict';
let taskPagesLoaded=false;let liveTasks=[],taskCursor=null,taskFilter='ALL',taskRefreshing=false,taskSubmitting=false,taskRequest=null,livePoll=null,taskDetailId=null,quoteTimer=null,quoteSerial=0;
const taskTerminal=new Set(['SUCCEEDED','PARTIAL_SUCCEEDED','FAILED','CANCELED','TIMED_OUT']);
const taskLabels={QUEUED:'排队中',PENDING:'待处理',SUBMITTING:'提交模型',RUNNING:'生成中',MATERIALIZING:'归档中',SUCCEEDED:'已完成',PARTIAL_SUCCEEDED:'部分完成',FAILED:'失败',CANCELED:'已取消',TIMED_OUT:'超时'};
const decodeConfig=value=>typeof value==='string'?JSON.parse(value):value||{};
const points=value=>Number(value||0).toLocaleString('zh-CN',{maximumFractionDigits:4});
function liveCapabilities(mode=draft().mode){return (cloudData?.capabilities||[]).filter(c=>c.operation.toLowerCase()===mode&&c.status==='ENABLED').map(c=>({...c,id:String(c.id),limits:decodeConfig(c.limits_config),defaults:decodeConfig(c.default_parameters)}));}
function liveCapability(){const d=draft(),all=liveCapabilities();if(d.mode==='image'&&d.refs?.length){const edit=all.find(c=>(c.limits.minRefs||0)>0);if(edit)return edit;}return all.find(c=>c.id===String(d.capabilityId))||all.find(c=>c.name===d.model)||all[0];}
function selectCapability(c,reset=false){if(!c)return;const d=draft(),limits=c.limits,defaults=c.defaults;d.capabilityId=c.id;d.model=c.name;d.count=Math.max(1,Math.min(Number(d.count)||1,limits.maxCount||1));
 if(reset||limits.ratios&&!limits.ratios.includes(d.ratio))d.ratio=defaults.ratio||d.ratio;
 if(reset||limits.resolutions&&!limits.resolutions.includes(d.resolution))d.resolution=defaults.resolution||d.resolution;
 if(d.mode==='video')d.videoSeconds=Math.max(limits.minSeconds||5,Math.min(limits.maxSeconds||10,Number(d.videoSeconds)||5));
 if(d.mode==='music'){d.musicSeconds=Math.max(1,Math.min(limits.maxSeconds||120,Number(d.musicSeconds)||30));d.musicSmart=false;}
}
const taskCloudHydrate=cloudHydrateDraft;cloudHydrateDraft=function(d,records){const model=d.model;taskCloudHydrate(d,records);d.model=model||'待配置';return d;};
const taskSync=syncComposer;syncComposer=function(){const c=liveCapability();if(c)selectCapability(c);taskSync();if(c)draft().model=c.name;const model=$('[data-menu="model"] span:last-child');if(model)model.textContent=c?.name||'暂无可用模型';
 if(draft().mode==='video'&&c?.defaults.adapter==='best-h3')$('#prompt').placeholder='最多 9 张图片、3 个音频和 3 个视频参考，描述你想生成的画面…';
 if(draft().mode==='audio'){const param=$('[data-menu="audio-mode"]');if(param)param.hidden=true;$('#prompt').placeholder='输入需要朗读的文本，并在下方描述声音特征…';}const enabled=!!c&&cloudConfig.cloudEnabled;$('#generate').disabled=taskSubmitting||cloudUploadsPending>0||!enabled||!isReady(normalizeDraft(draft()));$('#generate').title=cloudUploadsPending>0?'素材上传中，请等待上传完成':enabled?'提交真实生成任务；成功归档后结算积分':'当前模式暂无可执行模型';
 const quote=localQuote();$('#cost').textContent=quote?points(quote.points):'—';$('#cost-unit').textContent=quote?' 积分 / 本次':' / 待接入';
 if(draft().mode==='audio'&&!$('#voice-design'))$('.prompt-fields').insertAdjacentHTML('beforeend',`<label class="voice-design-label">声音描述<input id="voice-design" aria-label="声音描述" value="${esc(draft().voiceDesign||'自然清晰的普通话声音')}" maxlength="500"></label>`);
 if(draft().mode==='audio'&&$('#voice-design'))$('#voice-design').value=draft().voiceDesign||'自然清晰的普通话声音';
 const caption=$('.composer-caption');if(caption)caption.textContent=enabled?'真实模型任务 · 提交预占积分，归档成功后结算，失败自动退回':'此模式暂未接入模型，可以保存草稿';
};
function localQuote(){const c=liveCapability();if(!c)return null;const d=draft();let rate=Number(c.points_per_unit),units=d.mode==='image'?Number(d.count)||1:d.mode==='video'?Number(d.videoSeconds)||5:1;if(d.mode==='video')rate=({'480P':1,'768P':3,'1080P':5,'2K':7})[d.resolution]||3;return{points:rate*units,rate,units};}
const taskMenu=menu;menu=function(kind){const c=liveCapability(),d=draft();if(!['model','format','count','duration'].includes(kind))return taskMenu(kind);if(openMenu===kind){closeMenu();return;}closeMenu();openMenu=kind;const p=$('#popover');p.hidden=false;p.style.width='300px';
 if(kind==='model'){p.innerHTML='<div class="popover-title">已接入的生成模型</div>'+liveCapabilities().map(c=>`<button class="menu-item ${String(d.capabilityId)===c.id?'selected':''}" data-action="live-model" data-id="${c.id}"><span>◇ ${esc(c.name)}<small>${points(c.points_per_unit)} 积分 / ${c.billing_unit==='SECOND'?'秒':c.billing_unit==='IMAGE'?'张':'次'} · 参考图 ${c.limits.minRefs||0}–${c.limits.maxRefs||0} 张</small></span></button>`).join('')+(c?'':'<p class="helper cloud-model-empty">此模式暂无可执行模型</p>');return;}
 if(!c){p.innerHTML='<p class="helper cloud-model-empty">请先选择可用模型</p>';return;}
 if(kind==='format'){p.innerHTML=`<div class="format-section"><label>画面比例</label><div class="choices">${(c.limits.ratios||[]).map(r=>`<button class="choice ${d.ratio===r?'selected':''}" data-action="live-param" data-key="ratio" data-value="${esc(r)}">${esc(r)}</button>`).join('')}</div></div><div class="format-section"><label>分辨率</label><div class="choices">${(c.limits.resolutions||[]).map(r=>`<button class="choice ${d.resolution===r?'selected':''}" data-action="live-param" data-key="resolution" data-value="${esc(r)}">${esc(r)}</button>`).join('')}</div></div>`;return;}
 if(kind==='count'){p.innerHTML='<div class="popover-title">生成数量</div><div class="choices">'+Array.from({length:c.limits.maxCount||1},(_,i)=>`<button class="choice ${d.count===i+1?'selected':''}" data-count="${i+1}">${i+1}</button>`).join('')+'</div><p class="helper">按成功归档数量结算；未交付部分退回积分。</p>';return;}
 const values=d.mode==='video'?Array.from({length:(c.limits.maxSeconds||10)-(c.limits.minSeconds||5)+1},(_,i)=>i+(c.limits.minSeconds||5)):[5,15,30,60,90,120].filter(v=>v<=(c.limits.maxSeconds||120));p.innerHTML='<div class="popover-title">生成时长</div><div class="choices">'+values.map(v=>`<button class="choice" data-action="live-param" data-key="${d.mode==='video'?'videoSeconds':'musicSeconds'}" data-value="${v}">${v}s</button>`).join('')+'</div>';
};
actions['live-model']=el=>{selectCapability(liveCapabilities().find(c=>c.id===el.dataset.id),true);save();closeMenu();syncComposer();};
actions['live-param']=el=>{const key=el.dataset.key;if(!['ratio','resolution','videoSeconds','musicSeconds'].includes(key))return;draft()[key]=key.endsWith('Seconds')?Number(el.dataset.value):el.dataset.value;if(key==='musicSeconds')draft().musicSmart=false;save();closeMenu();syncComposer();};
window.studioAfterLoad=()=>refreshTasks(true).catch(cloudFail);
const taskCloudReset=cloudReset;cloudReset=function(){taskRetryKeys.clear();taskRetryPending.clear();taskPagesLoaded=false;liveTasks=[];taskCursor=null;taskDetailId=null;taskRequest=null;taskSubmitting=false;clearInterval(livePoll);livePoll=null;taskCloudReset();};
function taskCard(t){const terminal=taskTerminal.has(t.status),failure=['FAILED','TIMED_OUT'].includes(t.status);return `<article class="live-task-card" data-task-id="${t.id}"><div class="live-task-head"><span class="task-status ${failure?'failed':terminal?'done':'working'}">${esc(taskLabels[t.status]||t.status)}</span><span>${esc(t.model)}</span><time>${new Date(t.created).toLocaleString('zh-CN')}</time></div><p data-user-content>${esc(t.prompt)}</p>${!terminal?`<progress max="100" value="${Number(t.progress)||0}" aria-label="任务进度"></progress>`:''}${failure?`<div class="task-error">${esc(t.errorMessage||'任务失败')} · 未交付积分退回</div>`:''}<div class="live-task-footer"><small>${esc(t.taskNo)} · 预占 ${points(t.pricing?.reservedPoints)} 积分</small><div><button class="secondary-btn" data-action="task-detail" data-id="${t.id}">任务详情</button>${terminal?`<button class="secondary-btn" data-action="task-retry" data-id="${t.id}">再次生成</button>`:['QUEUED','PENDING'].includes(t.status)?`<button class="subtle-button" data-action="task-cancel" data-id="${t.id}">取消排队</button>`:''}</div></div></article>`;}
function renderConversationTasks(){const view=$('#view');view.querySelector('.conversation-tasks')?.remove();const tasks=liveTasks.filter(t=>t.conversationId===state.current);if(tasks.length){const existing=new Set(state.records.filter(r=>r.session===state.current).map(r=>r.taskId));view.insertAdjacentHTML('beforeend',`<section class="conversation-tasks"><h2>任务记录</h2>${tasks.filter(t=>!existing.has(t.id)||!taskTerminal.has(t.status)).map(taskCard).join('')}<button class="subtle-button" data-action="task-center">查看全部历史任务 →</button></section>`);}}
const taskFeed=renderFeed;renderFeed=function(){taskFeed();renderConversationTasks();};
function reconcileCreationFeed(){
 const view=$('#view'),existing=new Map([...view.querySelectorAll(':scope > .creation[data-record]')].map(node=>[node.dataset.record,node]));
 if(!existing.size){renderFeed();return;}
 const records=state.records.filter(r=>r.session===state.current&&!r.deleted),ids=new Set(records.map(r=>String(r.id)));
 for(const [id,node] of existing)if(!ids.has(id))node.remove();
 let cursor=view.querySelector('.feed-heading')?.nextElementSibling||null;
 for(const record of records){let node=existing.get(String(record.id));if(!node){const template=document.createElement('template');template.innerHTML=creation(record);node=template.content.firstElementChild;}
  if(node!==cursor)view.insertBefore(node,cursor);cursor=node.nextElementSibling;
 }
 renderConversationTasks();
}
function renderTaskCenter(){const data=taskFilter==='ALL'?liveTasks:taskFilter==='ACTIVE'?liveTasks.filter(t=>!taskTerminal.has(t.status)):liveTasks.filter(t=>t.status===taskFilter);$('#view').innerHTML=header('任务中心','每次生成都有记录，状态与积分实时同步。','<button class="secondary-btn" data-action="tasks-refresh">刷新状态</button>')+`<div class="tabs task-tabs">${[['ALL','全部任务'],['ACTIVE','进行中'],['SUCCEEDED','已完成'],['FAILED','失败']].map(([key,label])=>`<button class="tab ${taskFilter===key?'active':''}" data-action="task-filter" data-value="${key}">${label}</button>`).join('')}</div><div class="task-quota-line">可用 ${points(state.credits)} · 预占 ${points(cloudData?.quota?.reserved_points)} · 已消耗 ${points(cloudData?.quota?.consumed_points)} 积分 <button class="subtle-button" data-action="credits">查看积分流水</button></div><section class="task-list">${data.map(taskCard).join('')||'<div class="empty"><h2>暂无任务</h2><p>提交生成后，任务会保存在这里。</p></div>'}</section>${taskCursor?'<button class="secondary-btn" data-action="tasks-more">加载更早的任务</button>':''}`;}
const taskRender=render;render=function(){if(cloudData)for(const m of modes){const caps=liveCapabilities(m.id);m.models=caps.length?caps.map(c=>c.name):['暂无可用模型'];observedModels[m.id]=m.models;}taskRender();if(page==='tasks'){$('#page-name').textContent='任务中心';renderTaskCenter();}if(cloudUser&&page==='create'){$('.composer-caption').textContent='真实任务 · 提交预占积分，归档成功后结算，失败退回';if($('.quote-line'))$('.quote-line').textContent='模型请求、任务进度、生成资产和积分流水均保存至当前账号。';}};
async function refreshTasks(repaint=true){if(!cloudUser||taskRefreshing)return;taskRefreshing=true;const epoch=cloudEpoch;try{const data=await cloudRequest('/admin-api/aigc/tasks?limit=50');if(epoch!==cloudEpoch)return;const changed=data.tasks.some(t=>{const old=liveTasks.find(x=>x.id===t.id);return taskTerminal.has(t.status)&&(!old||old.status!==t.status);});const ids=new Set(data.tasks.map(t=>t.id));liveTasks=[...data.tasks,...(taskPagesLoaded?liveTasks.filter(t=>!ids.has(t.id)):[])];if(!taskPagesLoaded)taskCursor=data.nextId;cloudData.quota=data.quota;state.credits=data.quota.available_points;$('#credits').textContent=points(state.credits);
 if(changed){const assets=await cloudRequest('/admin-api/aigc/assets?limit=500');if(epoch!==cloudEpoch)return;let rows=assets.records,cursor=assets.nextId;while(cursor){const next=await cloudRequest('/admin-api/aigc/assets?limit=500&beforeId='+encodeURIComponent(cursor));if(epoch!==cloudEpoch)return;rows.push(...next.records);cursor=next.nextId;}state.records=rows.map(r=>({...r,src:(cloudConfig.apiBase||'')+r.contentPath}));}
 if(repaint){if(page==='tasks')renderTaskCenter();if(page==='create'){if(changed)reconcileCreationFeed();else renderConversationTasks();}if(page==='assets'&&changed)renderAssets();}
 if(taskDetailId&&$('.modal [data-task-detail]'))await showTaskDetail(taskDetailId,true);
 if(!livePoll)livePoll=setInterval(()=>{if(document.visibilityState!=='hidden')refreshTasks().catch(()=>{});},4000);
 }finally{taskRefreshing=false;}}
generate=async function(){if(!cloudRequire()||taskSubmitting)return;if(cloudUploadsPending>0){toast('素材上传中，请等待上传完成');return;}if(!isReady(normalizeDraft(draft()))){toast('请先填写创作描述');return;}const c=liveCapability();if(!c){toast('当前模式尚未接入生成模型');return;}taskSubmitting=true;syncComposer();const snapshot=structuredClone(draft());delete snapshot.modeDrafts;for(const field of ['refs','attachments'])snapshot[field]=(snapshot[field]||[]).map(({src,blobKey,...rest})=>rest);
 const fingerprint=JSON.stringify({conversationId:state.current,capabilityId:c.id,draft:snapshot});if(!taskRequest||taskRequest.fingerprint!==fingerprint)taskRequest={fingerprint,key:uid()};const epoch=cloudEpoch;
 try{save();await cloudFlush();await cloudRequest('/admin-api/aigc/tasks/quote',{method:'POST',body:JSON.stringify({operation:draft().mode.toUpperCase(),capabilityId:c.id,draft:snapshot})});const result=await cloudRequest('/admin-api/aigc/tasks',{method:'POST',body:JSON.stringify({conversationId:state.current,operation:snapshot.mode.toUpperCase(),capabilityId:c.id,clientRequestId:taskRequest.key,draft:snapshot})});if(epoch!==cloudEpoch)return;taskRequest=null;await refreshTasks();toast(result.reused?'已找回之前提交的任务，没有重复扣费':'任务已提交，可在任务中心查看状态');}
 catch(error){cloudFail(error);}finally{if(epoch===cloudEpoch){taskSubmitting=false;syncComposer();}}};actions.generate=generate;
actions['task-center']=()=>{navigate('tasks');if(cloudUser)refreshTasks().catch(cloudFail);};actions['tasks-refresh']=cloudAction(()=>refreshTasks());actions['task-filter']=el=>{taskFilter=el.dataset.value;renderTaskCenter();};
actions['tasks-more']=cloudAction(async()=>{if(!taskCursor)return;const data=await cloudRequest('/admin-api/aigc/tasks?limit=50&beforeId='+encodeURIComponent(taskCursor));const seen=new Set(liveTasks.map(t=>t.id));liveTasks.push(...data.tasks.filter(t=>!seen.has(t.id)));taskCursor=data.nextId;taskPagesLoaded=true;renderTaskCenter();});
const taskRetryKeys=new Map(),taskRetryPending=new Set();
async function restoreTaskInput(id){
 const epoch=cloudEpoch;await cloudFlush();if(epoch!==cloudEpoch)return null;
 const task=await cloudRequest('/admin-api/aigc/tasks/'+encodeURIComponent(id));if(epoch!==cloudEpoch)return null;
 const parameters=structuredClone(task.parameters||{}),mode=task.operation.toLowerCase();
 if(!modes.some(m=>m.id===mode))throw Error('原任务的创作类型暂不支持回填');
 const restoreReference=ref=>{const asset=state.records.find(r=>r.id===String(ref.assetId));if(!asset)throw Error('原任务的参考素材不可用，请先从回收站恢复素材');return {...ref,assetId:String(ref.assetId),src:asset.src,name:ref.name||asset.title||asset.prompt,type:ref.type||asset.mime};};
 parameters.refs=(parameters.refs||[]).map(restoreReference);parameters.attachments=(parameters.attachments||[]).map(restoreReference);
 const target=state.sessions.find(s=>s.id===task.conversationId)||session(),prior=normalizeDraft(target.draft),bank=structuredClone(prior.modeDrafts);
 const previous=structuredClone(prior);delete previous.modeDrafts;bank[prior.mode]=previous;
 // Replace input fields with the immutable task snapshot; retain drafts in other modes.
 const restored=normalizeDraft({...defaults(),...parameters,mode,model:task.model,prompt:task.prompt,modeDrafts:bank});delete restored._revision;
 restored.duration=(mode==='music'?restored.musicSeconds:restored.videoSeconds)+'s';if(mode==='music')restored.musicSmart=false;
 target.draft=restored;state.current=target.id;page='create';taskDetailId=null;closeModal();render();save();await cloudFlush();if(epoch!==cloudEpoch)return null;
 $('#prompt')?.focus();return {task,conversationId:target.id};
}

actions['task-retry']=cloudAction(async el=>{const id=el.dataset.id;if(!cloudRequire()||el.disabled||taskRetryPending.has(id))return;el.disabled=true;taskRetryPending.add(id);const key=taskRetryKeys.get(id)||uid(),epoch=cloudEpoch;taskRetryKeys.set(id,key);try{const restored=await restoreTaskInput(id);if(!restored||epoch!==cloudEpoch)return;await cloudRequest('/admin-api/aigc/tasks/'+id+'/retry',{method:'POST',body:JSON.stringify({clientRequestId:key,conversationId:restored.conversationId})});if(epoch!==cloudEpoch)return;taskRetryKeys.delete(id);await refreshTasks();toast('原任务输入已回填，新的生成任务已提交');}finally{taskRetryPending.delete(id);el.disabled=false;}});
actions['task-cancel']=cloudAction(async el=>{await cloudRequest('/admin-api/aigc/tasks/'+el.dataset.id+'/cancel',{method:'POST'});await refreshTasks();toast('排队任务已取消，预占积分已退回');});
async function showTaskDetail(id,update=false){const t=await cloudRequest('/admin-api/aigc/tasks/'+id);const body=`<div data-task-detail="${t.id}"><div class="task-detail-summary"><span class="task-status">${esc(taskLabels[t.status]||t.status)}</span><strong>${esc(t.model)}</strong><small>${esc(t.taskNo)}</small></div><p data-user-content>${esc(t.prompt)}</p><p>预占 ${points(t.pricing.reservedPoints)} 积分 · ${points(t.pricing.rate)} 积分 / ${esc(({IMAGE:'张',SECOND:'秒',REQUEST:'次',CHARACTER:'字'})[t.pricing.unit]||t.pricing.unit)}</p>${t.errorMessage?`<p class="${t.status==='FAILED'?'task-error':'helper'}">${esc(t.errorMessage)}</p>`:''}<h3>状态时间线</h3><ol class="task-timeline">${t.events.map(e=>`<li><strong>${esc(taskLabels[e.to]||e.to)}</strong><span>${esc(e.message)}</span><time>${new Date(e.created).toLocaleString('zh-CN')}</time></li>`).join('')}</ol>${t.results.length?`<h3>生成结果</h3><div class="task-result-links">${t.results.map(r=>r.assetId&&!r.trashed?`<button class="secondary-btn" data-action="task-open-asset" data-id="${r.assetId}">查看结果 ${r.index}</button>`:`<span>结果 ${r.index} · ${r.trashed?'已移入回收站':esc(r.status)}</span>`).join('')}</div>`:''}</div>`;
 if(update){const root=$('.modal [data-task-detail]');if(root)root.outerHTML=body;return;}taskDetailId=id;modal('生成任务详情',body,taskTerminal.has(t.status)?`<button class="primary-btn" data-action="task-retry" data-id="${id}">再次生成</button>`:'');}
actions['task-detail']=cloudAction(el=>showTaskDetail(el.dataset.id));actions['task-open-asset']=el=>{taskDetailId=null;closeModal();navigate('assets');preview(el.dataset.id);};
let ledgerCursor=null,ledgerRows=[];
function ledgerHTML(){return `<div class="cloud-quota"><div><small>可用积分</small><strong>${points(cloudData.quota.available_points)}</strong></div><div><small>任务预占</small><strong>${points(cloudData.quota.reserved_points)}</strong></div><div><small>累计消耗</small><strong>${points(cloudData.quota.consumed_points)}</strong></div></div><p class="helper">平台积分不是现金。提交预占，归档成功后结算，失败或未交付部分退回。</p><div class="ledger-list">${ledgerRows.map(r=>`<div class="ledger-row"><span><strong>${esc(({GRANT:r.remark?.startsWith('Stripe')?'充值到账':'积分发放',RESERVE:'生成预占',SETTLE:'生成结算',RELEASE:'积分退回',ADJUST:'调整'})[r.entry_type])}</strong><small>${esc(r.remark)}${r.task_id?' · 任务 '+esc(r.task_id):''}</small><time>${new Date(r.created).toLocaleString('zh-CN')}</time></span><span>可用 ${Number(r.available_delta)>0?'+':''}${points(r.available_delta)}<small>预占 ${points(r.reserved_delta)} · 消耗 ${points(r.consumed_delta)}</small></span></div>`).join('')||'<p>暂无流水</p>'}</div>${ledgerCursor?'<button class="secondary-btn" data-action="ledger-more">加载更早流水</button>':''}`;}
actions.credits=cloudAction(async()=>{if(!cloudRequire())return;taskDetailId=null;const data=await cloudRequest('/admin-api/aigc/quota/ledger?limit=50');ledgerRows=data.entries;ledgerCursor=data.nextId;cloudData.quota=data.quota;modal('积分与流水',ledgerHTML(),' ',true);});
actions['ledger-more']=cloudAction(async()=>{const data=await cloudRequest('/admin-api/aigc/quota/ledger?limit=50&beforeId='+ledgerCursor);ledgerRows.push(...data.entries);ledgerCursor=data.nextId;cloudData.quota=data.quota;modal('积分与流水',ledgerHTML(),' ',true);});
actions.regenerate=cloudAction(async el=>{const r=record(el.dataset.id);if(r?.taskId){await actions['task-retry']({dataset:{id:r.taskId},disabled:false});return;}await reedit(el.dataset.id,false);await generate();});
const taskReedit=reedit;reedit=async function(id,notify=true){const r=record(id);if(r?.taskId){const restored=await restoreTaskInput(r.taskId);if(restored&&notify)toast('原任务描述、参数和参考素材已载入');return;}taskReedit(id,notify);};actions.reedit=cloudAction(el=>reedit(el.dataset.id));
function liveVideoPlayer(r){return `<div class="video-player"><video data-record-media="${esc(r.id)}" ${window.StudioMedia?.deferred?'':`src="${esc(r.src)}"`} ${window.StudioMedia?.poster(r)?`poster="${esc(window.StudioMedia.poster(r))}"`:''} controls playsinline preload="metadata" aria-label="视频作品"></video><div class="video-feedback" role="status"><span data-video-message>视频加载中…</span><button type="button" class="secondary-btn" data-action="reload-video" hidden>重新加载视频</button></div></div>`;}
const taskMedia=media;media=function(r,asset=false){if(r.cloud&&r.mode==='video')return asset?`<video data-record-media="${esc(r.id)}" ${window.StudioMedia?.deferred?'':`src="${esc(r.src)}"`} ${window.StudioMedia?.poster(r)?`poster="${esc(window.StudioMedia.poster(r))}"`:''} preload="metadata" playsinline></video>`:liveVideoPlayer(r);if(r.cloud&&['audio','music'].includes(r.mode))return `<div class="audio-file">${asset?icon('audio'):`<audio controls src="${esc(r.src)}"></audio>`}<span>${esc(r.model)}</span></div>`;return taskMedia(r,asset);};
for(const eventName of ['loadedmetadata','error'])document.addEventListener(eventName,event=>{const video=event.target;if(!video.matches?.('video[data-record-media]'))return;const feedback=video.closest('.video-player')?.querySelector('.video-feedback');if(!feedback)return;if(eventName==='loadedmetadata'){feedback.hidden=true;return;}feedback.hidden=false;feedback.classList.add('is-error');feedback.querySelector('[data-video-message]').textContent='视频暂时无法播放，请重新加载或下载原文件';feedback.querySelector('button').hidden=false;},true);
actions['reload-video']=cloudAction(async el=>{const player=el.closest('.video-player'),video=player?.querySelector('video');if(!video||!cloudRequire())return;el.disabled=true;try{await cloudRequest('/admin-api/aigc/media-session',{method:'POST'});if(!player.isConnected)return;const feedback=player.querySelector('.video-feedback');feedback.classList.remove('is-error');feedback.querySelector('[data-video-message]').textContent='视频加载中…';feedback.querySelector('button').hidden=true;feedback.hidden=false;video.load();}finally{el.disabled=false;}});

const taskPreview=preview;preview=function(id){const r=record(id);if(r?.cloud&&['video','audio','music'].includes(r.mode)){taskDetailId=null;modal('生成媒体预览',`<p data-user-content>${esc(r.prompt)}</p>${r.mode==='video'?`<div class="real-video-preview">${liveVideoPlayer(r)}</div>`:`<audio class="audio-preview" controls src="${esc(r.src)}"></audio>`}`,actionBtn('download','下载原文件','download',id)+(r.taskId?`<button class="secondary-btn" data-action="task-detail" data-id="${r.taskId}">任务详情</button>`:''),true);return;}taskPreview(id);if(r?.cloud){const helper=$('.detail-sidebar .helper');if(helper)helper.textContent='作品已保存至个人资产。创作工具目前仅保存编辑草稿，具体图片处理功能尚待接通。';}};actions.preview=el=>preview(el.dataset.id);
document.addEventListener('input',event=>{if(event.target.id==='voice-design'){draft().voiceDesign=event.target.value;save();}if(event.target.id==='prompt'){$('#generate').disabled=taskSubmitting||!liveCapability()||!isReady(normalizeDraft(draft()));}});
document.querySelector('nav').insertAdjacentHTML('beforeend',`<button class="nav-item" data-nav="tasks">${icon('folder')}<span>任务中心</span></button>`);
if(location.hash.slice(1).split('/')[0]==='tasks')page='tasks';render();
